// Generated by scripts/derive-overrides.mjs from packages/mobile-core/src/screens/helpers-screen.tsx. Do not edit.
import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { KeyboardAvoidingView, Platform, Pressable, ScrollView, View } from 'react-native';
import Animated, { FadeInUp } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { api, type CareRole, type Me } from '@kuvos/mobile-core/api';
import { Button } from '@kuvos/mobile-core/components/button';
import { Text, TextInput } from '@kuvos/mobile-core/components/text';
import { Tomo } from '@kuvos/mobile-core/components/tomo';
import { signInMetadata } from '@kuvos/mobile-core/config';
import { onboardingSteps } from '@kuvos/mobile-core/onboarding-draft';
import { colors } from '@kuvos/mobile-core/theme';

// Last onboarding step: invite a helper (patient) or the patient (caregiver), or skip to Today.
export function HelpersScreen({ patientId, role }: { patientId: string; role: CareRole }) {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const [me, setMe] = useState<Me>();
  const [email, setEmail] = useState('');
  const [sentTo, setSentTo] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    api<Me>('/me').then(setMe, () => undefined);
  }, []);

  const membership = me?.memberships.find((item) => item.patient.id === patientId);
  const invitingPatient = role === 'PATIENT';
  const userFirst = me?.user.name.trim().split(/\s+/)[0] ?? '';
  const patientFirst = membership?.patient.name.trim().split(/\s+/)[0] ?? '';

  const greeting = invitingPatient
    ? `${patientFirst ? `${patientFirst}’s` : 'The'} plan is ready! Want ${patientFirst || 'them'} to follow it on their own phone?`
    : `Your plan is ready${userFirst ? `, ${userFirst}` : ''}! Who helps you? I can keep them in the loop.`;

  async function invite() {
    if (busy) return;
    const contact = email.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact)) {
      setError('Enter a valid email address.');
      return;
    }
    setBusy(true);
    setError('');
    try {
      await api(`/patients/${patientId}/invitations`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ contact, role, ...signInMetadata }),
      });
      setSentTo(contact);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The invitation could not be sent.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      className="flex-1 bg-cloud"
      style={{ paddingTop: insets.top }}
    >
      <View
        accessible
        accessibilityLabel={`Step ${onboardingSteps} of ${onboardingSteps}`}
        className="min-h-12 flex-row items-center justify-end gap-3 px-5"
      >
        <Text className="text-2xs font-semibold uppercase tracking-eyebrow text-slate">
          Step {onboardingSteps} of {onboardingSteps}
        </Text>
        <View className="flex-row gap-1.5">
          {Array.from({ length: onboardingSteps }, (_, index) => (
            <View key={index} className="h-1 w-5 rounded-full bg-deep-blue" />
          ))}
        </View>
      </View>

      <ScrollView
        className="flex-1"
        contentContainerClassName="flex-grow justify-end gap-3 px-5 pb-5 pt-2"
        keyboardShouldPersistTaps="handled"
      >
        <View className="items-center pb-3">
          <Tomo size={104} mood={sentTo ? 'happy' : 'idle'} label="Tomo" />
        </View>
        {!!me && (
          <Animated.View entering={FadeInUp.duration(320)} className="max-w-[86%] self-start rounded-3xl rounded-tl-lg bg-white px-4 py-3">
            <Text className="text-lg leading-6 text-ink">{greeting}</Text>
          </Animated.View>
        )}
        {!!sentTo && (
          <>
            <Animated.View entering={FadeInUp.duration(320)} className="max-w-[80%] self-end rounded-3xl rounded-tr-lg bg-deep-blue px-4 py-3">
              <Text className="text-lg leading-6 text-white">Invite {sentTo}</Text>
            </Animated.View>
            <Animated.View entering={FadeInUp.delay(250).duration(320)} className="max-w-[86%] self-start rounded-3xl rounded-tl-lg bg-white px-4 py-3">
              <Text className="text-lg leading-6 text-ink">
                Done! They’ll get an email and join by signing in with that address. No care details
                are in the email.
              </Text>
            </Animated.View>
          </>
        )}
      </ScrollView>

      <Animated.View
        className="gap-3 rounded-t-3xl border-t border-line bg-white px-5 pt-4"
        style={{ paddingBottom: insets.bottom + 12 }}
      >
        {sentTo ? (
          <Button title="Go to Today" size="hero" onPress={() => router.replace('/today')} />
        ) : (
          <>
            <TextInput
              autoFocus
              blurOnSubmit={false}
              editable={!busy}
              accessibilityLabel={invitingPatient ? `${patientFirst || 'Their'} email address` : 'Helper’s email address'}
              autoCapitalize="none"
              autoComplete="email"
              autoCorrect={false}
              className="min-h-14 rounded-3xl border border-line bg-cloud px-4 text-lg text-ink"
              keyboardType="email-address"
              placeholder={invitingPatient ? `${patientFirst || 'Their'} email` : 'Their email'}
              placeholderTextColor={colors.slate}
              returnKeyType="send"
              textContentType="emailAddress"
              value={email}
              onChangeText={(value) => {
                setEmail(value);
                setError('');
              }}
              onSubmitEditing={invite}
            />
            {!!error && (
              <Text selectable accessibilityRole="alert" className="rounded-2xl bg-coral/10 p-4 text-sm text-ink">
                {error}
              </Text>
            )}
            <Button title="Send invite" loading={busy} disabled={!email.trim()} onPress={invite} />
            <Pressable
              accessibilityRole="button"
              className="min-h-12 items-center justify-center"
              disabled={busy}
              style={({ pressed }) => ({ opacity: pressed ? 0.6 : 1 })}
              onPress={() => router.replace('/today')}
            >
              <Text className="text-base font-semibold text-deep-blue">
                {invitingPatient ? 'Not now' : 'I’ll do it myself'}
              </Text>
            </Pressable>
          </>
        )}
      </Animated.View>
    </KeyboardAvoidingView>
  );
}
